(7250051, 1126383, 97225, '<td valign="top">Wonderful layers of patterns. The wavy part the man is walking on appears to be undulating. One of my ribbon choices.</td>', 'Wonderful layers of patterns. The wavy part the man is walking on appears to be undulating. One of my ribbon choices.', '2014-08-11 00:21:32.000000', NULL, 1),
