(7250549, 1126502, 173844, '<td valign="top">Perspective and depth of field make this wooden post and greenery engaging.  The sense of downward motion is fascinating.</td>', 'Perspective and depth of field make this wooden post and greenery engaging.  The sense of downward motion is fascinating.', '2014-08-12 01:44:07.000000', NULL, 1),
(7250550, 1126383, 173844, '<td valign="top">Enjoyable illusion of this man walking on water.  Along with the striking patterns of the brickwork is the more subtle echo of arched windows.  Very nice.</td>', 'Enjoyable illusion of this man walking on water.  Along with the striking patterns of the brickwork is the more subtle echo of arched windows.  Very nice.', '2014-08-12 01:47:22.000000', NULL, 1),
