(7250661, 1126079, 156466, '<td valign="top">Very nicely done and processed.</td>', 'Very nicely done and processed.', '2014-08-12 15:55:11.000000', NULL, 1),
(7250662, 1126470, 173844, '<td valign="top">I personally love the cast shadow of leaves, with its implicit motion, and this is a nice sepia example.  I''d have to pull back mighty far, however, to call this a discernible pattern.  Aside from that, which I suppose is apposite, I like this image.</td>', 'I personally love the cast shadow of leaves, with its implicit motion, and this is a nice sepia example.  I''d have to pull back mighty far, however, to call this a discernible pattern.  Aside from that, which I suppose is apposite, I like this image.', '2014-08-12 15:55:40.000000', NULL, 1),
(7250663, 1126291, 156466, '<td valign="top">I understand why you put the feet in, but when I scroll down I like it better without them.</td>', 'I understand why you put the feet in, but when I scroll down I like it better without them.', '2014-08-12 15:56:50.000000', NULL, 1),
(7250666, 1126134, 173844, '<td valign="top">There''s an enjoyable yin/yangish feeling to this contrast between pattern and texture.  The use of black and white enhances the impact of the image.</td>', 'There''s an enjoyable yin/yangish feeling to this contrast between pattern and texture.  The use of black and white enhances the impact of the image.', '2014-08-12 15:59:34.000000', NULL, 1),
(7250667, 1126403, 156466, '<td valign="top">Nicely shot and processed, but the lines from the beams and blocks all seem crooked and are making me bonkers.  6 that I''d love to score higher.</td>', 'Nicely shot and processed, but the lines from the beams and blocks all seem crooked and are making me bonkers.  6 that I''d love to score higher.', '2014-08-12 16:01:54.000000', NULL, 1),
