(7250717, 1126482, 74588, '<td valign="top">hey    8</td>', 'hey    8', '2014-08-12 18:21:05.000000', NULL, 1),
(7250718, 1126084, 74588, '<td valign="top">believe you   8</td>', 'believe you   8', '2014-08-12 18:21:32.000000', NULL, 1),
(7250719, 1126291, 74588, '<td valign="top">thats it   8</td>', 'thats it   8', '2014-08-12 18:22:09.000000', NULL, 1),
(7250720, 1126497, 173844, '<td valign="top">Lovely, peacock-y image.  Wonderful that you can find such extravagant pattern and color in entropy, which the dictionary calls, in part, "the measure of the randomness, disorder, or chaos in a system."  In my personal house of worship I''d love to see this very stained glass window.</td>', 'Lovely, peacock-y image.  Wonderful that you can find such extravagant pattern and color in entropy, which the dictionary calls, in part, "the measure of the randomness, disorder, or chaos in a system."  In my personal house of worship I''d love to see this very stained glass window.', '2014-08-12 18:25:17.000000', NULL, 1),
(7250721, 1126291, 173844, '<td valign="top">Once the feet are added to this pattern of bricks and paths you have a narrative, and the stakes are raised.  So the imagination is subtly invited into the image, the viewer is engaged and the photo is successful.</td>', 'Once the feet are added to this pattern of bricks and paths you have a narrative, and the stakes are raised.  So the imagination is subtly invited into the image, the viewer is engaged and the photo is successful.', '2014-08-12 18:36:18.000000', NULL, 1),
(7250722, 1125989, 173844, '<td valign="top">A shimmering pattern in a colorful composition.  Engaging.</td>', 'A shimmering pattern in a colorful composition.  Engaging.', '2014-08-12 18:38:25.000000', NULL, 1),
(7250723, 1126439, 173844, '<td valign="top">Compelling pattern that could be crystalline structure under a scanning microscope or architectural sleight of hand.  This image exemplifies strict "pattern" more than any other in the challenge.</td>', 'Compelling pattern that could be crystalline structure under a scanning microscope or architectural sleight of hand.  This image exemplifies strict "pattern" more than any other in the challenge.', '2014-08-12 18:43:37.000000', NULL, 1),
(7250724, 1126372, 173844, '<td valign="top">Nicely positioned structure that engages a sense of pattern from its new perspective, enhanced by its striking coloration and clever title.  Also looks like stylized rapids in a river.  Object lesson in constructing whimsy from the straightforward.</td>', 'Nicely positioned structure that engages a sense of pattern from its new perspective, enhanced by its striking coloration and clever title.  Also looks like stylized rapids in a river.  Object lesson in constructing whimsy from the straightforward.', '2014-08-12 18:48:43.000000', NULL, 1),
(7250725, 1125936, 173844, '<td valign="top">I''m intrigued by the very bizarreness of this image.  Clever and idiosyncratic.  Once you can do this you can do anything!</td>', 'I''m intrigued by the very bizarreness of this image.  Clever and idiosyncratic.  Once you can do this you can do anything!', '2014-08-12 18:51:46.000000', NULL, 1),
(7250728, 1126259, 173844, '<td valign="top">Beautiful colors in this exotic (because it''s not English) pattern of paper lanterns.  A feast for the eyes.</td>', 'Beautiful colors in this exotic (because it''s not English) pattern of paper lanterns.  A feast for the eyes.', '2014-08-12 18:55:10.000000', NULL, 1),
(7250729, 1126104, 173844, '<td valign="top">Lovely aerial photograph of Levittown.  Okay, it''s a leaf.  But it''s a fine example of how one pattern can suggest something completely otherwise.  In its own right, it''s a splendid evocation of beauty in decay.<br/>Or are those toxic waste dumps.</td>', 'Lovely aerial photograph of Levittown.  Okay, it''s a leaf.  But it''s a fine example of how one pattern can suggest something completely otherwise.  In its own right, it''s a splendid evocation of beauty in decay.Or are those toxic waste dumps.', '2014-08-12 19:00:51.000000', NULL, 1),
(7250732, 1126153, 173844, '<td valign="top">Nice how this backlit leaf becomes a blazing torch.</td>', 'Nice how this backlit leaf becomes a blazing torch.', '2014-08-12 19:03:17.000000', NULL, 1),
(7250737, 1125936, 58634, '<td valign="top">Creative and interesting</td>', 'Creative and interesting', '2014-08-12 19:21:54.000000', NULL, 1),
